const shopLogo=(className='')=>`<img class="shop-logo ${className}" src="/logo.svg" alt="Party &amp; Home logo" width="100" height="100">`;
const $=s=>document.querySelector(s);
function refreshOrderTotals(){
 persistDraft();
 for(const l of state.cart){const element=document.querySelector(`[data-cart-qty="${l.key}"]`);const line=element?.closest('.cart-line');if(line)line.querySelector('.cart-line-controls>strong').textContent=money(l.qty*l.price);}
 for(const l of state.cart){const el=document.querySelector(`[data-line-total="${l.key}"]`);if(el)el.textContent=money(l.qty*l.price);}
 for(const [selector,value] of [['[data-transaction-total]',money(total())],['[data-transaction-units]',units()],['[data-transaction-lines]',state.cart.length]]){const el=document.querySelector(selector);if(el)el.textContent=value;}
 const amount=total();const totalElement=document.querySelector('.order-total strong');if(totalElement)totalElement.textContent=money(amount);
 const checkoutAmount=document.querySelector('.checkout-button span');if(checkoutAmount)checkoutAmount.textContent=money(amount);
 const count=document.querySelector('.order-subtotal span:last-child');if(count)count.textContent=units()+' '+(units()===1?'unit':'units');
}
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(n/100);
const date=s=>new Date(s).toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric',timeZone:'Africa/Johannesburg'});
const day=s=>new Date(s).toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'});
const uid=()=>crypto.randomUUID?.()||'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16)),levels=['p1','p2','p3','p4','p5'];
const paths={bag:'M6 7h12l2 14H4L6 7Zm3 0V5a3 3 0 0 1 6 0v2',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',box:'m3 7 9-4 9 4-9 5-9-5Zm0 0v10l9 5 9-5V7M12 12v10M7.5 5l9 4.5',file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8',chart:'M4 20h17M7 16V9m5 7V4m5 12v-5',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Zm0 9a3 3 0 1 0 6 0 3 3 0 0 0-6 0',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5M3 10a7 7 0 1 0 14 0 7 7 0 0 0-14 0',x:'m6 6 12 12M6 18 18 6',minus:'M5 12h14',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',print:'M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v8H6z',check:'m5 12 4 4L19 6',refresh:'M20 8A8 8 0 1 0 20 16M20 3v6h-6',store:'M4 10v11h16V10M3 3h18v7c-2 2-4 2-6 0-2 2-4 2-6 0-2 2-4 2-6 0V3Zm6 18v-7h6v7',cart:'M2 3h3l3 12h11l3-9H6M9 20h.01M18 20h.01',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3h.01',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3m14-18a4 4 0 0 1 0 8m5 10v-3a4 4 0 0 0-3-3M5 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0',logout:'M9 4H3v16h6m5-13 5 5-5 5m-5-5h14',menu:'M3 6h18M3 12h18M3 18h18',edit:'m15 3 6 6-12 12H3v-6L15 3Zm-3 3 6 6',archive:'M3 3h18v5H3zM5 8v13h14V8M9 12h6'};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;}
const state={data:null,page:'sale',search:'',category:'',inventoryDepartment:'',level:'p1',cart:[],kind:'invoice',filter:'active',docTab:'all',period:30,modal:null,edit:null,image:'',doc:null,busy:false,uploading:false,local:true,customer:{},requestId:null,convertId:null};
const nav=[['sale','grid','Point of sale'],['invoices','file','Invoicing'],['orders','cart','Sales orders'],['stockmaster','box','Stockmaster'],['inventory','box','Products & stock'],['departments','store','Departments'],['customers','users','Customers'],['documents','file','Sales documents'],['reports','chart','Sales reports']];
const button=(label,action,cls='',data='',disabled=false)=>`<button type="button" class="button ${cls}" data-action="${action}" ${data} ${disabled?'disabled':''}>${label}</button>`;
const actionIcon=(name,action,label,data='')=>`<button type="button" class="icon-button" data-action="${action}" aria-label="${escape(label)}" ${data}>${icon(name,18)}</button>`;
const field=(label,input,wide=false)=>`<label class="field ${wide?'wide':''}"><span>${label}</span>${input}</label>`;
const input=(name,value='',extra='')=>`<input name="${name}" value="${escape(value)}" ${extra}>`;
const priceInput=(name,value=0)=>`<div class="money-input"><span>R</span>${input(name,(value/100).toFixed(2),'type="number" min="0" max="1000000" step="0.01" required')}</div>`;
function empty(title,detail,cta='',name='box'){return `<div class="empty"><div class="empty-icon">${icon(name,34)}</div><h3>${escape(title)}</h3><p>${escape(detail)}</p>${cta}</div>`;}
const picture=(p,large=false)=>`<div class="picture ${large?'large':''}">${p.image?`<img src="${escape(p.image)}" alt="${escape(p.name)}">`:icon('box',large?60:24)}</div>`;
const products=()=>state.data?.products||[],docs=()=>state.data?.documents||[],lines=()=>state.data?.lines||[];
const supervisor=()=>['owner','supervisor'].includes(state.data?.role),active=()=>products().filter(p=>p.active),low=()=>active().filter(p=>p.stock<=p.low);
const docTotal=d=>lines().filter(l=>l.document_id===d.id).reduce((n,l)=>n+l.qty*l.price,0);
const total=()=>state.cart.reduce((n,l)=>n+l.qty*l.price,0),units=()=>state.cart.reduce((n,l)=>n+l.qty,0);
const docNo=d=>`${d.kind==='invoice'?'INV':'QUO'}-${String(d.seq).padStart(5,'0')}`;
const departments=()=>state.data?.departments||[...new Set(products().map(p=>p.category))].sort();
function departmentOptions(selected){return departments().map(name=>`<option value="${escape(name)}" ${name.toLowerCase()===selected.toLowerCase()?'selected':''}>${escape(name)}</option>`).join('');}
function departmentFilter(id,selected){return `<label class="department-filter"><span>Department</span><select id="${id}" aria-label="Filter by department"><option value="">All departments</option>${departmentOptions(selected)}</select></label>`;}
function departmentsPage(){return `<div class="department-layout"><section class="panel settings-card"><div class="panel-title"><div><h2>Add departments</h2><p>Enter one department per line to add several at once.</p></div>${icon('plus')}</div><form data-form="departments">${field('Department names','<textarea name="names" required rows="7" placeholder="Party supplies&#10;Homeware&#10;Cleaning&#10;Stationery"></textarea>')}<button class="button primary" data-save>${icon('plus',17)}Save departments</button></form><p class="helper">Departments you add here are available in every product form and department filter. Existing product categories are included automatically.</p></section><section class="panel"><div class="panel-title"><div><h2>Your departments</h2><p>${departments().length} departments available</p></div>${icon('store')}</div><div class="table-scroll"><table><thead><tr><th>Department</th><th>Products</th><th></th></tr></thead><tbody>${departments().map(name=>{const count=products().filter(p=>p.category.toLowerCase()===name.toLowerCase()).length;return `<tr><td><strong>${escape(name)}</strong></td><td>${count}</td><td>${button('Remove','remove-department','small',`data-name="${escape(name)}"`,count>0)}</td></tr>`;}).join('')}</tbody></table></div>${!departments().length?empty('Start with your departments','Add all your department names here before creating products.','','store'):''}<p class="panel-empty">A department can be removed once all its products, including archived products, have been moved to another department.</p></section></div>`;}
let toastTimer;
function notify(message){clearTimeout(toastTimer);$('#notifications').innerHTML=`<div class="toast" role="status"><span>${escape(message)}</span>${actionIcon('x','dismiss','Dismiss notification')}</div>`;toastTimer=setTimeout(()=>$('#notifications').innerHTML='',6000);}
async function request(path,payload){const r=await fetch(path,payload===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not complete this request.');return d;}
async function refresh(renderPage=true){try{state.data=await request('/api/pos');restoreDraft();if(renderPage)render();return true;}catch(e){if(!state.data)await showLogin(e.message);else notify(e.message);return false;}}
async function save(payload,message){if(state.busy)return null;state.busy=true;setBusy();try{const r=await request('/api/pos',payload);await refresh(false);notify(message);return r;}catch(e){notify(e.message);return null;}finally{state.busy=false;setBusy();}}
function setBusy(){document.querySelectorAll('[data-save]').forEach(b=>{b.disabled=state.busy||state.uploading;});}
function go(page){state.customerHistory=null;state.page=page;if(page==='invoices')state.kind='invoice';if(page==='orders')state.kind='quote';state.search='';render();}
function render(){const d=state.data;if(!d)return;persistDraft();const page=state.page;const heading={sale:['Let’s make someone’s day.','Find a product, build an order, and you’re ready to go.'],stockmaster:['Your Stockmaster.','Product pictures, descriptions and packaging at a glance.'],inventory:['Your shelves, sorted.','Manage your items, prices and stock in one place.'],documents:['Every sale, on record.','Quotations to get started. Invoices to make it official.'],reports:['See how business is doing.','A clear view of what’s selling and how often.'],departments:['Organise your departments.','Add your departments once, then choose one for every product.'],invoices:['Invoice','Customer details, line items and totals.'],orders:['Sales order','Prepare a sales order and convert it to an invoice.'],customers:['Your customers, remembered.','Save customer details once and reuse them on every sale.'],settings:['Make it your own.','Your shop details and the people who keep it running.']}[page];
$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand">${shopLogo()}<div><strong class="brand-name"><span class="party-word"><i>P</i><i>A</i><i>R</i><i>T</i><i>Y</i></span><span class="home-word"> &amp; HOME</span></strong><span>YOUR SHOP. YOUR WORKSPACE.</span></div></div><div class="workspace-label">SHOP WORKSPACE</div><nav>${nav.map(([id,ic,label])=>`<button data-action="nav" data-page="${id}" class="${page===id?'selected':''}">${icon(ic)}${label}${id==='inventory'&&low().length?`<span class="nav-count">${low().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-note"><div class="note-icon">${icon('box',23)}</div><strong>Everyday essentials.<br>Extra special occasions.</strong><p>A colourful shop. A simpler day.</p></div><div class="sidebar-bottom"><button data-action="nav" data-page="settings" class="${page==='settings'?'selected':''}">${icon('settings')}Settings & access</button><div class="profile"><span class="avatar">${escape(d.user.name[0].toUpperCase())}</span><div><strong>${d.role==='owner'?'Shop owner':escape(d.user.name)}</strong><span>${supervisor()?'Supervisor access':'Sales staff'}</span></div>${actionIcon('logout','logout','Sign out')}</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu',22)}</button>${shopLogo('topbar-logo')}<span>${escape(d.shop?.name||'Party & Home')}</span><span class="breadcrumb-slash">/</span><strong>${escape(page==='settings'?'Settings & access':nav.find(n=>n[0]===page)?.[2])}</strong></div><div class="top-actions"><span class="today-date">${date(new Date())}</span>${actionIcon('refresh','refresh','Refresh stock and sales')}<span class="live-label"><span></span>Workspace</span></div></header><div class="page-content ${['invoices','orders'].includes(page)?'transaction-content':''}">${['invoices','orders'].includes(page)?'':`<div class="page-heading"><div><div class="eyebrow">A LITTLE COLOUR. A LOT OF POSSIBILITY.</div><h1>${heading[0]}</h1><p>${heading[1]}</p></div>${page==='customers'?button(icon('plus',18)+'New customer','new-customer','primary'):['inventory','stockmaster'].includes(page)?button(icon('plus',18)+'Add product','new-product','primary'):page==='documents'?button(icon('plus',18)+'New sale','nav','primary','data-page="sale"'):page==='reports'?button(icon('upload',18)+'Export sales','export','', '',!report().documents.length):`<div class="heading-tag">${shopLogo()}<span>PARTY ESSENTIALS<br><strong>&amp; everyday favourites</strong></span></div>`}</div>`}${['invoices','orders'].includes(page)?transactionPage():page==='sale'?salePage():page==='stockmaster'?stockmasterPage():page==='inventory'?inventoryPage():page==='customers'?customersPage():page==='documents'?documentsPage():page==='reports'?reportsPage():page==='departments'?departmentsPage():settingsPage()}<footer class="page-footer"><span class="footer-brand">PARTY <b>&amp; HOME</b></span><p>Every occasion. Every home.</p><small>All prices in ZAR</small></footer></div></main></div>`;
if(d.setup){state.modal='setup';}renderDialog();}
function stats(){const today=day(new Date()),sales=docs().filter(d=>d.kind==='invoice'&&day(d.created)===today);return `<div class="stat-row"><div class="stat"><span class="stat-icon peach">${icon('file',21)}</span><div><span>Today’s sales</span><strong>${money(sales.reduce((n,d)=>n+docTotal(d),0))}</strong></div><small>${sales.length} invoices</small></div><div class="stat"><span class="stat-icon mint">${icon('box',21)}</span><div><span>Products available</span><strong>${active().length}</strong></div><small>${active().reduce((n,p)=>n+p.stock,0)} units in stock</small></div><button class="stat stat-button" data-action="low-stock"><span class="stat-icon lilac">${icon('alert',21)}</span><div><span>Low stock items</span><strong>${low().length}</strong></div><small>${low().length?'Time for a top-up':'Looking good'}</small></button></div>`;}
const searchBox=(placeholder)=>`<div class="search-box"><span>${icon('search',18)}</span><input id="search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${escape(state.search)}"><span class="search-key">SKU</span></div>`;
function salePage(){const filtered=active().filter(p=>(state.category===''||p.category.toLowerCase()===state.category.toLowerCase())&&productMatches(p,state.search));return `${stats()}<div class="sale-layout"><section class="catalogue"><div class="catalogue-toolbar">${searchBox('Search products by name or code…')}${button(icon('plus',18)+'<span>Add item</span>','new-product')}</div><div class="department-toolbar">${departmentFilter("sale-department",state.category)}${button(icon("store",17)+"Manage departments","nav","small",'data-page="departments"')}</div><div class="section-label"><h2>${escape(state.category===''?'Your products':state.category)}</h2><span>${filtered.length} items <span class="muted">· Choose an item to add</span></span></div>${filtered.length?`<div class="product-grid">${filtered.map(p=>`<button class="product-card" data-action="add-product" data-id="${escape(p.id)}"><div class="product-visual">${picture(p,true)}<span class="stock-pill ${p.stock<=p.low?'warning':''}">${p.stock===0?'Out of stock':`${p.stock} in stock`}</span><span class="add-circle">${icon('plus',18)}</span></div><div class="product-info"><small>${escape(p.sku)} <span>· ${escape(p.unit)}</span></small><h3>${escape(p.name)}</h3><div><strong>${money(p[state.level])}</strong><span>${escape(p.category)}</span></div></div></button>`).join('')}</div>`:`<div class="catalogue-empty">${empty(state.search?'No products found':'Your shelves are ready',state.search?'Try another name or product code.':'Add your first product with a picture, stock count and selling prices.',button(icon('plus',18)+'Add your first product','new-product','primary'))}<div class="first-steps"><span>${icon('check',16)}Your own product pictures</span><span>${icon('check',16)}Five selling prices</span><span>${icon('check',16)}Live stock counts</span></div></div>`}</section><aside class="order-panel"><div class="order-head"><div><h2>Current order <span>${state.cart.length}</span></h2><p>A good day starts with a sale.</p></div>${icon('bag',23)}</div><div class="order-type">${['invoice','quote'].map(k=>`<button data-action="kind" data-kind="${k}" class="${state.kind===k?'active':''}">${icon('file',16)}${k==='invoice'?'Invoice':'Quotation'}</button>`).join('')}</div><div class="price-level"><span>Selling price</span><div class="levels">${levels.map(l=>`<button data-action="level" data-level="${l}" class="${l===state.level?'active':''}">${l.toUpperCase()}</button>`).join('')}</div></div><div class="cart-lines">${state.cart.length?state.cart.map(l=>`<div class="cart-line"><div class="cart-line-top"><div><strong>${escape(l.name)}</strong><small>${escape(l.sku)} · ${escape(l.unit)}${!l.productId?' · No stock tracking':''}</small></div>${actionIcon('x','remove-line','Remove '+l.name,`data-key="${l.key}"`)}</div><div class="cart-line-controls"><div class="quantity"><button data-action="qty" data-key="${l.key}" data-delta="-1" aria-label="Decrease quantity">${icon('minus',13)}</button><input id="qty-${l.key}" aria-label="Quantity for ${escape(l.name)}" type="number" min="1" max="1000000" step="1" value="${l.qty}" data-cart-qty="${l.key}"><button data-action="qty" data-key="${l.key}" data-delta="1" aria-label="Increase quantity">${icon('plus',13)}</button></div><label class="inline-price"><span>R</span><input id="price-${l.key}" aria-label="Unit price for ${escape(l.name)}" type="number" min="0" max="1000000" step="0.01" value="${(l.price/100).toFixed(2)}" data-cart-price="${l.key}"></label><strong>${money(l.qty*l.price)}</strong></div></div>`).join(''):empty('Your order starts here','Tap a product to add it, or enter an item manually.','','cart')}</div><button class="manual-button" data-action="manual">${icon('plus',17)}Add a manual item</button><div class="order-footer"><div class="order-subtotal"><span>Items</span><span>${units()} ${units()===1?'unit':'units'}</span></div><div class="order-total"><span>Total</span><strong>${money(total())}</strong></div><p class="stock-explanation">${icon(state.kind==='invoice'?'box':'file',14)}${state.kind==='invoice'?'Stock updates when you save the invoice.':'A quotation does not change your stock.'}</p><button class="button primary checkout-button" data-action="checkout" ${!state.cart.length?'disabled':''}>${state.kind==='invoice'?'Create invoice':'Create quotation'}<span>${money(total())}</span></button>${state.cart.length?'<button class="text-button clear-order" data-action="clear">Clear order</button>':''}</div></aside></div>`;}
function inventoryPage(){const ps=products().filter(p=>(state.filter==='archived'?!p.active:p.active&&(state.filter!=='low'||p.stock<=p.low))&&(!state.inventoryDepartment||p.category.toLowerCase()===state.inventoryDepartment.toLowerCase())&&`${p.name} ${p.sku}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="inventory-summary"><span><strong>${active().length}</strong> active products</span><span><strong>${active().reduce((n,p)=>n+p.stock,0)}</strong> units on hand</span><span class="orange-text"><strong>${low().length}</strong> need attention</span>${supervisor()?`<span>${icon('lock',14)}Cost visibility enabled</span>`:''}</div><section class="panel"><div class="table-toolbar"><div class="tabs">${[['active','Active products'],['low','Low stock'],['archived','Archived']].map(([k,v])=>`<button data-action="inventory-filter" data-filter="${k}" class="${state.filter===k?'active':''}">${v}</button>`).join('')}</div>${searchBox('Search name or SKU…')}${departmentFilter("inventory-department",state.inventoryDepartment)}</div><div class="table-scroll"><table><thead><tr><th>Product</th><th>Stock</th>${levels.map(l=>`<th>${l.toUpperCase()}</th>`).join('')}${supervisor()?`<th>${icon('lock',12)} Cost</th>`:''}<th>Manage</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="product-cell">${picture(p)}<div><strong>${escape(p.name)}</strong><small>${escape(p.sku)} · ${escape(p.category)}</small></div></div></td><td><span class="badge ${p.stock<=p.low?'amber':'green'}">${p.stock} ${escape(p.unit)}</span></td>${levels.map(l=>`<td>${money(p[l])}</td>`).join('')}${supervisor()?`<td class="cost-cell">${money(p.cost)}</td>`:''}<td><div class="row-actions">${actionIcon('edit','edit-product','Edit '+p.name,`data-id="${escape(p.id)}"`)}${actionIcon('box','stock','Adjust stock for '+p.name,`data-id="${escape(p.id)}"`)}${supervisor()?actionIcon('archive','archive','Archive or restore '+p.name,`data-id="${escape(p.id)}"`):''}</div></td></tr>`).join('')}</tbody></table></div>${!ps.length?empty('A place for your products',products().length?'No products match this view.':'Add a product to start tracking stock and making sales.',button(icon('plus',18)+'Add product','new-product','primary')):''}</section><section class="panel history-panel"><div class="panel-title"><div><h2>Stock activity</h2><p>The latest 200 receipts, adjustments and invoice deductions.</p></div>${icon('box')}</div>${state.data.movements?.length?`<div class="table-scroll"><table><thead><tr><th>Date</th><th>Product</th><th>Change</th><th>Reason</th><th>Recorded by</th></tr></thead><tbody>${state.data.movements.map(m=>`<tr><td>${date(m.created)}</td><td>${escape(products().find(p=>p.id===m.product_id)?.name||'Item')}</td><td><span class="badge ${m.delta>=0?'green':'amber'}">${m.delta>0?'+':''}${m.delta}</span></td><td>${escape(m.reason)}</td><td class="muted">${escape(m.actor)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="panel-empty">Stock movements will appear here as you add items and invoice sales.</p>'}</section>`;}
function documentsPage(){const ds=docs().filter(d=>(!state.customerHistory||d.details?.customerId===state.customerHistory)&&(state.docTab==='all'||state.docTab===d.kind)&&`${d.customer} ${docNo(d)}`.toLowerCase().includes(state.search.toLowerCase()));return `${state.customerHistory?`<div class="customer-history-filter"><span>Documents for <strong>${escape(customers().find(c=>c.id===state.customerHistory)?.name||'customer')}</strong></span>${button('Show all documents','nav','small','data-page="documents"')}</div>`:''}<section class="panel"><div class="table-toolbar"><div class="tabs">${[['all','All documents'],['quote','Sales orders'],['invoice','Invoices']].map(([k,v])=>`<button data-action="doc-tab" data-tab="${k}" class="${state.docTab===k?'active':''}">${v}</button>`).join('')}</div>${searchBox('Search customer or number…')}</div><div class="table-scroll"><table><thead><tr><th>Document</th><th>Customer</th><th>Date</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr><td><strong class="document-number">${icon('file',17)}${docNo(d)}</strong></td><td>${escape(d.customer)}</td><td>${date(d.created)}</td><td><span class="badge ${d.kind==='invoice'?'green':'amber'}">${d.kind==='invoice'?'Invoiced':docs().some(x=>x.quote_id===d.id)?'Converted':'Quotation'}</span></td><td class="amount-cell">${money(docTotal(d))}</td><td><div class="row-actions">${button('View / print','view-document','small',`data-id="${escape(d.id)}"`)}${button('Copy to new','copy-order','small',`data-id="${escape(d.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div>${!ds.length?empty('Every sale has a story','Saved quotations and invoices will appear here. Start by creating an order.',button('Open point of sale','nav','primary','data-page="sale"'),'file'):''}</section>`;}
function report(){const cutoff=new Date();cutoff.setUTCDate(cutoff.getUTCDate()-(state.period-1));const start=day(cutoff);const documents=docs().filter(d=>d.kind==='invoice'&&day(d.created)>=start),ids=new Set(documents.map(d=>d.id)),ls=lines().filter(l=>ids.has(l.document_id));const revenue=ls.reduce((n,l)=>n+l.qty*l.price,0),units=ls.reduce((n,l)=>n+l.qty,0),sellers=Object.values(ls.reduce((o,l)=>{const k=l.product_id||l.name;o[k]??={name:l.name,qty:0,revenue:0};o[k].qty+=l.qty;o[k].revenue+=l.qty*l.price;return o;},{})).sort((a,b)=>b.qty-a.qty);const count=state.period===7?7:10,size=state.period/count;const bars=Array.from({length:count},(_,i)=>{const a=new Date(cutoff);a.setUTCDate(a.getUTCDate()+Math.floor(i*size));const b=new Date(cutoff);b.setUTCDate(b.getUTCDate()+Math.floor((i+1)*size));return {label:a.toLocaleDateString('en-ZA',{day:'numeric',month:'short'}),value:documents.filter(d=>day(d.created)>=day(a)&&day(d.created)<day(b)).reduce((n,d)=>n+docTotal(d),0)};});return {documents,lines:ls,revenue,units,sellers,bars};}
function reportsPage(){const r=report(),max=Math.max(...r.bars.map(b=>b.value),1);return `<div class="report-filter"><span>${icon('chart',17)}Reporting period</span><select id="period" aria-label="Reporting period">${[7,30,90].map(p=>`<option value="${p}" ${p===state.period?'selected':''}>Last ${p} days</option>`).join('')}</select><small>Invoices only · Quotations are excluded</small></div><div class="stat-row report-stats"><div class="stat"><span class="stat-icon peach">${icon('file',21)}</span><div><span>Sales revenue</span><strong>${money(r.revenue)}</strong></div></div><div class="stat"><span class="stat-icon mint">${icon('bag',21)}</span><div><span>Invoices created</span><strong>${r.documents.length}</strong></div></div><div class="stat"><span class="stat-icon lilac">${icon('box',21)}</span><div><span>Units sold per day</span><strong>${(r.units/state.period).toFixed(1)}<small> units / day</small></strong></div></div></div><div class="report-grid"><section class="panel"><div class="panel-title"><div><h2>Sales over time</h2><p>${r.units} units sold · Average invoice ${money(r.documents.length?Math.round(r.revenue/r.documents.length):0)}</p></div><span class="badge neutral">ZAR</span></div><div class="chart" role="img" aria-label="${escape('Sales revenue over the last '+state.period+' days: '+money(r.revenue))}">${r.bars.map(b=>`<div class="chart-column"><span class="bar-value">${b.value?money(b.value):''}</span><div class="chart-track"><div class="chart-bar" style="height:${b.value/max*100}%" title="${escape(b.label+': '+money(b.value))}"></div></div><span class="chart-label">${escape(b.label)}</span></div>`).join('')}</div>${!r.documents.length?'<p class="chart-note">Your sales chart will grow with your first invoice.</p>':''}</section><section class="panel bestsellers"><div class="panel-title"><div><h2>What’s selling</h2><p>Ranked by units sold</p></div>${icon('chart')}</div>${r.sellers.length?r.sellers.slice(0,10).map((s,i)=>`<div class="seller"><span class="seller-rank">${i+1}</span><div><strong>${escape(s.name)}</strong><small>${s.qty} units · ${(s.qty/state.period).toFixed(1)} per day</small></div><strong>${money(s.revenue)}</strong></div>`).join(''):empty('Your bestsellers, soon','Invoice a sale to start seeing your most popular products.','','chart')}</section></div>`;}
function settingsPage(){const d=state.data,owner=d.role==='owner';return `<div class="settings-grid">${printingSettings()}<section class="panel settings-card"><div class="panel-title"><div><h2>Shop details</h2><p>These appear on your printed sales documents.</p></div>${icon('store',21)}</div><form data-form="shop"><div class="form-grid">${field('Shop name',input('name',d.shop.name,`required maxlength="120" ${owner?'':'disabled'}`),true)}${field('Contact details',input('contact',d.shop.contact,`maxlength="200" ${owner?'':'disabled'}`),true)}${field('Business address',`<textarea name="address" maxlength="500" ${owner?'':'disabled'}>${escape(d.shop.address)}</textarea>`,true)}${field('Currency',input('currency','South African rand (ZAR)','readonly'),true)}</div>${owner?'<button class="button primary" data-save>Save shop details</button>':''}</form><div class="info-callout">${icon('lock',19)}<div><strong>Cost prices stay private</strong><p>Only supervisors and the owner can see or edit costs. Costs never appear on customer documents.</p></div></div></section><section class="panel settings-card"><div class="panel-title"><div><h2>Team access</h2><p>Give the right people the right access.</p></div>${icon('users',21)}</div>${owner?`<div class="member-row"><span class="avatar">${escape(d.user.name[0].toUpperCase())}</span><div><strong>${escape(d.user.email)}</strong><small>Shop owner · Supervisor permissions</small></div><span class="badge green">Owner</span></div>${d.members.map(m=>`<div class="member-row"><span class="avatar">${escape(m.email[0].toUpperCase())}</span><div><strong>${escape(m.email)}</strong><small>${m.role==='supervisor'?'Can view and edit costs':'Sales, products and stock · Costs hidden'}</small></div>${actionIcon('edit','edit-member','Update '+m.email,`data-email="${escape(m.email)}" data-role="${m.role}"`)}${actionIcon('x','remove-member','Remove '+m.email,`data-email="${escape(m.email)}"`)}</div>`).join('')}<form class="team-form" data-form="member">${field(state.local?'Team member username':'Team member email',input(state.local?'username':'email','',state.local?'id="team-email" type="text" required autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="e.g. cashier1"':'id="team-email" type="email" required maxlength="200" placeholder="name@example.com"'))}${field('Role','<select name="role" id="team-role"><option value="staff">Sales staff</option><option value="supervisor">Supervisor</option></select>')}${state.local?field('Set / reset password',input('password','','type="password" autocomplete="new-password" placeholder="Required for a new team member"')):''}<button class="button primary" data-save>${icon('plus',17)}Save team member</button></form><p class="helper">${state.local?'New team members need a password to sign in. Leave the password blank to keep an existing password.':'Roles control access inside the POS. Also grant team members website access through Sites sharing.'}</p>`:empty('Managed by your shop owner','Ask the owner to add team members or change your role.','','lock')}</section><section class="panel settings-card"><div class="panel-title"><div><h2>How your stock works</h2><p>Keep your numbers right.</p></div>${icon('box',21)}</div><div class="info-list">${['Count stock in the same unit you sell, for example packs. Invoicing 3 packs removes 3 from stock.','Quotations reserve no stock. Convert a quotation into an invoice when the sale is confirmed.','Manual items can have any description and price. They do not affect inventory.','Invoices are final once saved. Record inventory corrections using a stock adjustment and a clear reason.','Prices are final selling prices. Configure included VAT and banking details in Print settings.'].map(t=>`<p>${icon('check',17)}<span>${t}</span></p>`).join('')}</div></section></div>`;}
function modal(title,subtitle,content,wide=false,closable=true){return `<div class="overlay"><section class="modal ${wide?'wide-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${escape(title)}</h2><p>${escape(subtitle)}</p></div>${closable?actionIcon('x','close-modal','Close dialog'):''}</header>${content}</section></div>`;}
const footer=(label,cancel=true)=>`<div class="modal-footer">${cancel?button('Cancel','close-modal'):''}<button class="button primary" data-save>${label}</button></div>`;
function renderDialog(){const m=state.modal,p=state.edit;let html='';if(state.doc)html=documentView(state.doc);
if(m==='setup')html+=modal('Make yourself at home.','Set up your shop to start adding products and making sales.',`<form data-form="setup"><div class="setup-visual">${icon('store',45)}</div><div class="form-grid">${field('Shop name',input('name','Party & Home','required maxlength="120" autofocus'),true)}${field('Phone or email',input('contact','','maxlength="200" placeholder="Contact details for your invoices"'),true)}${field('Business address','<textarea name="address" maxlength="500"></textarea>',true)}</div><p class="helper">You’ll be the shop owner with supervisor access. Add your team later in Settings & access.</p>${footer('Open my shop',false)}</form>`,false,false);
if(m==='customer')html+=customerModal();
if(m==='pick-customer')html+=customerPicker();
if(m==='pick-stock')html+=stockPicker();
if(m==='product')html+=modal(p?'Edit product':'A new addition.','A picture, a stock count, and your prices. That’s all you need.',`<form data-form="product"><div class="product-form-layout"><div class="image-upload"><div id="image-preview">${state.image?`<img src="${escape(state.image)}" alt="Product preview" style="width:100%;height:180px;object-fit:contain">`:`${icon('box',46)}<p>A picture makes it easier</p>`}</div><span>JPG, PNG or WebP · Up to 2 MB</span><label class="button">${icon('upload',17)}<span id="upload-label">Upload picture</span><input id="upload-image" type="file" accept="image/jpeg,image/png,image/webp"></label>${button('Remove picture','remove-image','small')}</div><div class="form-grid">${field('Product name / short description',input('name',p?.name,'required maxlength="160" placeholder="e.g. White paper plates, 20 pack" autofocus'),true)}${field('Detailed description (optional)',`<textarea name="description" maxlength="1000" rows="3" placeholder="Colour, material, size or other identifying details">${escape(p?.description)}</textarea>`,true)}${field('Packaging / pack size',input('packaging',p?.packaging,'maxlength="160" placeholder="e.g. 12 x 100 pieces per carton"')+'<small class="packaging-help">Describe the pack contents. Stock is counted in the selling unit below.</small>',true)}${field('Item code / SKU',input('sku',p?.sku,'required maxlength="80" placeholder="e.g. PP-001"'))}${field('Department',`<select name="category" id="product-department" required><option value="">Select department</option>${departmentOptions(p?.category||'')}</select><details class="department-quick-add"><summary>Add departments</summary><textarea id="quick-departments" aria-label="New department names" placeholder="One department per line"></textarea><button type="button" class="button small" data-action="quick-departments" data-save>Save departments</button></details>`)}${field('Selling unit',input('unit',p?.unit||'Pack','required maxlength="40"'))}${field(p?'Stock on hand (use Adjust stock to change)':'Opening stock count',input('stock',p?.stock||0,`type="number" required min="0" max="1000000" step="1" ${p?'readonly':''}`))}${field('Low stock alert at',input('low',p?.low??5,'type="number" required min="0" max="1000000" step="1"'))}${supervisor()?field('Cost per unit · Supervisor only',priceInput('cost',p?.cost||0)):''}</div></div><div class="form-section-title"><h3>Selling prices</h3><span>Enter all five price levels manually.</span></div><div class="five-prices">${levels.map(l=>field(l.toUpperCase(),priceInput(l,p?.[l]||0))).join('')}</div>${footer(p?'Save changes':'Add product')}</form>`,true);
if(m==='stock')html+=modal('Keep your stock in check.',`${p.name} · Currently ${p.stock} ${p.unit}`,`<form data-form="stock"><div class="form-grid">${field('Quantity to add or remove',input('delta','','type="number" min="-1000000" max="1000000" step="1" required placeholder="e.g. 20 to receive, or -3 to remove" autofocus'),true)}${field('Reason',input('reason','','required maxlength="300" placeholder="e.g. New delivery, stock count correction"'),true)}</div><p class="helper">Positive numbers receive stock; negative numbers remove it. Every adjustment is recorded.</p>${footer('Save adjustment')}</form>`);
if(m==='manual')html+=modal('Add it your way.','Manual items won’t change your product stock.',`<form data-form="manual"><div class="form-grid">${field('Item description',input('name','','required maxlength="160" placeholder="e.g. Delivery or custom party bundle" autofocus'),true)}${field('Selling unit',input('unit','Each','required maxlength="40"'))}${field('Quantity',input('qty',1,'type="number" min="1" max="1000000" step="1" required'))}${field('Unit selling price',priceInput('price'),true)}</div>${footer('Add to order')}</form>`);
if(m==='checkout')html+=modal(state.kind==='invoice'?'Process invoice':'Save sales order / quotation',state.kind==='invoice'?'Saving this invoice deducts the sold quantities from stock.':'Sales order / quotation · Your stock will stay unchanged.',`<form data-form="checkout"><div class="checkout-customer-tools">${button(icon('users',16)+'Saved customer','pick-customer')}${button(icon('plus',16)+'New customer','new-customer')}</div><div class="form-grid">${field('Customer name',input('customer',state.customer.customer,'maxlength="200" placeholder="Walk-in customer" autofocus'),true)}${field('Phone or email',input('contact',state.customer.contact,'maxlength="300"'),true)}${field('Customer address',`<textarea name="address" maxlength="500">${escape(state.customer.address)}</textarea>`,true)}${state.kind==='invoice'?field('Payment method / terms',input('payment',state.customer.payment||'Cash','required maxlength="80" list="payments"')+'<datalist id="payments"><option>Cash</option><option>Card</option><option>EFT</option><option>On account</option></datalist>',true):''}${field('Notes',`<textarea name="notes" maxlength="1000">${escape(state.customer.notes)}</textarea>`,true)}</div><div class="checkout-summary"><span>${state.cart.length} line items · ${units()} units · ${state.level.toUpperCase()}</span><strong>${money(total())}</strong></div><p class="helper">Review the details, then save. Your printable document opens immediately. The app records payment terms; it does not collect payment.</p>${checkoutFooter()}</form>`);
if(m==='clear')html+=modal('Clear this draft?','The unsaved items and customer details will be removed.',`<div class="modal-footer">${button('Keep order','close-modal')}${button('Clear order','confirm-clear','primary')}</div>`);
if(m==='archive')html+=modal(p.active?'Archive this product?':'Restore this product?',`${p.name} ${p.active?'will be hidden from Point of sale. Stock and sales history will remain.':'will be available in Point of sale again.'}`,`<div class="modal-footer">${button('Cancel','close-modal')}<button class="button primary" data-save data-action="confirm-archive">${p.active?'Archive product':'Restore product'}</button></div>`);
if(m==='remove-member')html+=modal('Remove team access?',`${state.memberEmail} will no longer be able to use the POS.`,`<div class="modal-footer">${button('Cancel','close-modal')}<button class="button primary" data-save data-action="confirm-remove-member">Remove access</button></div>`);
if(m==='convert')html+=modal('Confirm this sale?','An invoice will be created at the quoted prices and the sold quantities will be deducted from stock.',`<form data-form="convert">${field('Payment method / terms',input('payment','Cash','required maxlength="80" autofocus'))}<div class="checkout-summary"><span>Invoice total</span><strong>${money(docTotal(state.doc))}</strong></div>${footer('Create invoice & deduct stock')}</form>`);
if(m==='removeDepartment')html+=modal('Remove this department?',state.removeDepartment,`<div class="modal-footer">${button('Cancel','close-modal')}<button class="button primary" data-save data-action="confirm-remove-department">Remove department</button></div>`);
$('#dialogs').innerHTML=html;setBusy();setTimeout(()=>$('#dialogs [autofocus]')?.focus(),20);}
function documentView(d){return printDocument(d);}
async function showLogin(error=''){let auth;try{auth=await request('/api/auth/status');}catch{auth={local:false,hasOwner:true};}state.local=auth.local;state.data=null;$('#dialogs').innerHTML='';$('#app').innerHTML=`<div class="login-screen"><section class="login-brand-panel">${shopLogo()}<div class="login-wordmark"><span class="party-word"><i>P</i><i>A</i><i>R</i><i>T</i><i>Y</i></span><span class="home-word"> &amp; HOME</span></div><h1>Every occasion.<br>Every home.</h1><p>A little colour makes every day brighter.</p><span class="login-brand-caption">YOUR PRODUCTS. YOUR PEOPLE. YOUR SHOP.</span></section><section class="login-content"><div class="login-card"><span class="login-kicker">PARTY &amp; HOME · POINT OF SALE</span><h2>${auth.hasOwner?'Welcome back.':'Welcome to your shop.'}</h2><p>${auth.hasOwner?'Sign in and get your shop day started.':'Welcome. Choose a username and password to create your shop owner account.'}</p>${auth.local?`<form data-form="login" data-setup="${!auth.hasOwner}" class="login-form"><div class="form-grid">${field('Username',input('username','','type="text" required autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Choose a username" autofocus'),true)}${field('Password',input('password','',`type="password" required autocomplete="${auth.hasOwner?'current-password':'new-password'}"`),true)}</div><p id="login-error" role="alert">${escape(error==='Please sign in to continue.'?'':error)}</p><button class="button primary" data-save>${auth.hasOwner?'Sign in':'Create owner account'}</button></form>`:`<p>${escape(error)}</p><a class="button primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT</a>`}<small class="muted">Every occasion. Every home. All in one place.</small></div></section></div>`;}
function productModal(p=null){state.edit=p;state.image=p?.image||'';state.modal='product';state.newProductId=uid();renderDialog();}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,p=products().find(p=>p.id===el.dataset.id);if(state.busy&&a!=='dismiss')return;
if(a==='nav')go(el.dataset.page);
if(a==='menu'){$('.sidebar').classList.toggle('mobile-open');return;}
if(a==='refresh'){if(await refresh())notify('Stock and sales refreshed.');}
if(a==='dismiss')$('#notifications').innerHTML='';
if(a==='logout'){if(state.cart.length){notify('Clear or save your current order before signing out.');return;}if(state.local){await request('/api/auth/logout',{});persistDraft();state.customer={};state.loadedDraft=null;state.modal=null;state.doc=null;await showLogin();}else location.href='/signout-with-chatgpt?return_to=%2F';}
if(a==='customer-history'){state.page='documents';state.search='';state.docTab='all';state.customerHistory=el.dataset.id;render();}
if(['new-customer','pick-customer'].includes(a)&&!['checkout','pick-customer'].includes(state.modal))state.customerReturnModal=null;
if(['new-customer','pick-customer'].includes(a)&&state.modal==='checkout'){state.customerReturnModal='checkout';const form=$('[data-form=checkout]');if(form)state.customer={...state.customer,...Object.fromEntries(new FormData(form))};}
if(a==='new-customer'){state.editCustomer=null;state.customerReturn=['invoices','orders','sale'].includes(state.page);state.modal='customer';renderDialog();}
if(a==='edit-customer'){state.editCustomer=customers().find(c=>c.id===el.dataset.id);state.customerReturn=false;state.modal='customer';renderDialog();}
if(a==='archive-customer'){const c=customers().find(c=>c.id===el.dataset.id);if(await save({action:'archiveCustomer',id:c.id,active:!c.active},c.active?'Customer archived.':'Customer restored.'))render();}
if(a==='pick-customer'){state.customerSearch='';state.modal='pick-customer';renderDialog();}
if(a==='use-customer'){chooseCustomer(el.dataset.id);state.modal=state.customerReturnModal||null;state.customerReturnModal=null;render();}
if(a==='walk-in'){state.customer={notes:state.customer.notes};render();}
if(a==='copy-order'){copyOrder(el.dataset.id);}
if(a==='print-saved'){state.doc=docs().find(d=>d.id===el.dataset.id);renderDialog();}
if(a==='pick-stock'){state.stockSearch='';state.modal='pick-stock';renderDialog();}
if(a==='pick-product'){if(!addStock(p))return;state.modal=null;render();}
if(a==='new-product')productModal();
if(a==='edit-product')productModal(p);
if(a==='category'){state.category=el.dataset.category;render();}
if(a==='low-stock'){state.page='inventory';state.filter='low';state.search='';render();}
if(a==='inventory-filter'){state.filter=el.dataset.filter;render();}
if(a==='doc-tab'){state.docTab=el.dataset.tab;render();}
if(a==='add-product'){if(addStock(p))render();}
if(a==='kind'){state.kind=el.dataset.kind;render();}
if(a==='level'){state.level=el.dataset.level;state.cart.forEach(l=>{const p=products().find(p=>p.id===l.productId);if(p)l.price=p[state.level];});render();}
if(a==='remove-line'){state.cart=state.cart.filter(l=>l.key!==el.dataset.key);render();}
if(a==='qty'){const l=state.cart.find(l=>l.key===el.dataset.key);l.qty=Math.max(1,Math.min(1000000,l.qty+Number(el.dataset.delta)));render();}
if(a==='manual'&&state.cart.length>=100){notify('A document can contain up to 100 lines.');return;}
if(a==='manual'||a==='clear'){state.modal=a;renderDialog();}
if(a==='confirm-clear'){state.cart=[];state.customer={};state.modal=null;render();}
if(a==='checkout'){if(!validateOrder())return;state.requestId=uid();state.modal='checkout';renderDialog();}
if(a==='stock'||a==='archive'){state.edit=p;state.modal=a;renderDialog();}
if(a==='close-modal'){if(state.modal==='setup')return;if(state.modal==='checkout'){const f=$('[data-form="checkout"]');if(f)state.customer={...state.customer,...Object.fromEntries(new FormData(f))};}state.modal=null;renderDialog();}
if(a==='remove-image'){state.image='';$('#image-preview').innerHTML=icon('box',46);}
if(a==='view-document'){state.doc=docs().find(d=>d.id===el.dataset.id);renderDialog();}
if(a==='close-doc'){state.doc=null;state.modal=null;renderDialog();}
if(a==='print')window.print();
if(a==='convert'){state.convertId=uid();state.modal='convert';renderDialog();}
if(a==='confirm-archive'){if(await save({action:'archive',id:state.edit.id,active:!state.edit.active},'Product updated.')){state.modal=null;render();}}
if(a==='edit-member'){$('#team-email').value=el.dataset.email;$('#team-role').value=el.dataset.role;$('#team-email').focus();}
if(a==='remove-member'){state.memberEmail=el.dataset.email;state.modal='remove-member';renderDialog();}
if(a==='confirm-remove-member'){if(await save({action:'member',email:state.memberEmail,role:'remove'},'Team access removed.')){state.modal=null;render();}}
if(a==='export')exportSales();
if(a==='quick-departments'){const names=$('#quick-departments').value.split(/\r?\n/).map(n=>n.trim()).filter(Boolean);const result=await save({action:'departments',names},'Departments saved.');if(result){$('#product-department').innerHTML='<option value="">Select department</option>'+departmentOptions(names[0]);$('#quick-departments').value='';}}
if(a==='remove-department'){state.removeDepartment=el.dataset.name;state.modal='removeDepartment';renderDialog();}
if(a==='confirm-remove-department'){if(await save({action:'removeDepartment',name:state.removeDepartment},'Department removed.')){state.modal=null;render();}}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.cartQty||el.dataset.cartPrice){const l=state.cart.find(l=>l.key===(el.dataset.cartQty||el.dataset.cartPrice)),value=Number(el.value);if(l&&el.value!==''&&Number.isFinite(value)){if(el.dataset.cartQty&&Number.isInteger(value)&&value>=1&&value<=1000000)l.qty=value;if(el.dataset.cartPrice&&value>=0&&value<=1000000)l.price=Math.round(value*100);refreshOrderTotals();}}if(state.modal==='checkout'&&['customer','contact','address','payment','notes'].includes(el.name)){state.customer[el.name]=el.value;persistDraft();}if(e.target.dataset.customer){state.customer[e.target.dataset.customer]=e.target.value;persistDraft();}if(e.target.id==='customer-search'){const pos=e.target.selectionStart;state.customerSearch=e.target.value;renderDialog();const el=$('#customer-search');el.focus();try{el.setSelectionRange(pos,pos);}catch{}}if(e.target.id==='stock-search'){const pos=e.target.selectionStart;state.stockSearch=e.target.value;renderDialog();const el=$('#stock-search');el.focus();try{el.setSelectionRange(pos,pos);}catch{}}if(e.target.id==='search'){const value=e.target.value,position=e.target.selectionStart;state.search=value;render();const el=$('#search');el.focus();try{el.setSelectionRange(position,position);}catch{}}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='stockmaster-department'){state.masterDepartment=el.value;render();}if(el.id==='stockmaster-filter'){state.masterFilter=el.value;render();}if(el.id==='transaction-level'){state.level=el.value;state.cart.forEach(l=>{const p=products().find(p=>p.id===l.productId);if(p)l.price=p[state.level];});render();}if(el.dataset.cartQty){const l=state.cart.find(l=>l.key===el.dataset.cartQty);l.qty=Math.max(1,Math.min(1000000,Math.trunc(Number(el.value)||1)));el.value=l.qty;refreshOrderTotals();}if(el.dataset.cartPrice){const l=state.cart.find(l=>l.key===el.dataset.cartPrice);l.price=Math.max(0,Math.min(100000000,Math.round(Number(el.value)*100)||0));el.value=(l.price/100).toFixed(2);refreshOrderTotals();}if(el.id==='sale-department'){state.category=el.value;render();}if(el.id==='inventory-department'){state.inventoryDepartment=el.value;render();}if(el.id==='period'){state.period=Number(el.value);render();}if(el.id==='upload-image'){const file=el.files?.[0];if(!file)return;if(file.size>2000000){notify('Choose a picture smaller than 2 MB.');return;}state.uploading=true;setBusy();$('#upload-label').textContent='Uploading…';try{const f=new FormData();f.append('file',file);const r=await fetch('/api/images',{method:'POST',body:f}),d=await r.json();if(!r.ok)throw new Error(d.error);state.image=d.url;$('#image-preview').innerHTML=`<img src="${escape(d.url)}" alt="Product preview" style="width:100%;height:180px;object-fit:contain">`;}catch(e){notify(e.message);}finally{state.uploading=false;setBusy();if($('#upload-label'))$('#upload-label').textContent='Upload picture';}}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(state.busy)return;const type=form.dataset.form,f=Object.fromEntries(new FormData(form)),printAfter=e.submitter?.dataset.printAfter==='true';let result;
if(type==='login'){state.busy=true;setBusy();try{await request(form.dataset.setup==='true'?'/api/auth/setup':'/api/auth/login',f);state.modal=null;await refresh();}catch(e){$('#login-error').textContent=e.message;}finally{state.busy=false;setBusy();}return;}
if(type==='customer'){const customerId=state.editCustomer?.id||uid();result=await save({action:'customer',...f,id:customerId,version:state.editCustomer?.version},'Customer saved.');if(result&&state.customerReturn)chooseCustomer(customerId);}
if(type==='printing')result=await save({action:'printing',...f,vat_rate:Math.round(Number(f.vat_rate||0)*100)},'Print settings saved.');
if(type==='scan'){const product=active().find(p=>p.sku.toLowerCase()===f.sku.trim().toLowerCase());if(product){if(addStock(product,Number(f.qty)))render();$('#quick-sku')?.focus();}else{state.stockSearch=f.sku.trim();state.modal='pick-stock';renderDialog();}return;}
if(type==='setup'||type==='shop')result=await save({action:type,...f},type==='setup'?'Your shop is ready. Add your first product.':'Shop details saved.');
if(type==='product'){const payload={action:'product',...f,id:state.edit?.id||state.newProductId,version:state.edit?.version,image:state.image,stock:Number(f.stock),low:Number(f.low),cost:Math.round(Number(f.cost||0)*100)};levels.forEach(l=>payload[l]=Math.round(Number(f[l])*100));result=await save(payload,state.edit?'Product updated.':'Product added to your shelves.');}
if(type==='departments'){const names=f.names.split(/\r?\n/).map(n=>n.trim()).filter(Boolean);result=await save({action:'departments',names},'Departments saved.');}
if(type==='stock')result=await save({action:'stock',id:state.edit.id,delta:Number(f.delta),reason:f.reason},'Stock count updated.');
if(type==='manual'){state.cart.push({key:uid(),productId:null,name:f.name,sku:'MANUAL',unit:f.unit,qty:Number(f.qty),price:Math.round(Number(f.price)*100)});state.modal=null;render();return;}
if(type==='member'){if(state.local&&!state.data.members.some(m=>m.email.toLowerCase()===(f.username??f.email).trim().toLowerCase())&&!f.password){notify('Set a password for this new team member.');return;}result=await save({action:'member',...f},'Team access saved.');}
if(type==='checkout'){if(!validateOrder())return;state.customer={...state.customer,...f};result=await save({action:'document',id:state.requestId,kind:state.kind,level:state.level,...state.customer,lines:state.cart},state.kind==='invoice'?'Invoice saved. Stock updated.':'Quotation saved. Stock unchanged.');if(result){state.cart=[];state.customer={};state.doc=docs().find(d=>d.id===result.id);persistDraft();}}
if(type==='convert'){result=await save({action:'document',id:state.convertId,kind:'invoice',quoteId:state.doc.id,payment:f.payment},'Quotation invoiced. Stock updated.');if(result)state.doc=docs().find(d=>d.id===result.id);}
if(result){state.modal=type==='customer'?state.customerReturnModal||null:null;state.customerReturnModal=null;render();if(type==='checkout'&&printAfter){await Promise.all([...document.querySelectorAll('.print-pages img')].map(i=>i.decode?.().catch(()=>{})));window.print();}}
});
function exportSales(){const r=report(),rows=[['Invoice','Date','Customer','Item','SKU','Quantity','Unit price (ZAR)','Total (ZAR)'],...r.lines.map(l=>{const d=docs().find(d=>d.id===l.document_id);return [docNo(d),date(d.created),d.customer,l.name,l.sku,l.qty,(l.price/100).toFixed(2),(l.qty*l.price/100).toFixed(2)];})];const csv=rows.map(r=>r.map(c=>{let s=String(c);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`sales-${day(new Date())}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey&&!state.modal&&['invoices','orders'].includes(state.page)){if(e.target.dataset.cartQty){e.preventDefault();document.querySelector(`[data-cart-price="${e.target.dataset.cartQty}"]`)?.focus();return;}if(e.target.dataset.cartPrice){e.preventDefault();$('#quick-sku')?.focus();return;}}if(state.modal==='pick-stock'&&e.key==='Enter'&&e.target.id==='stock-search'){e.preventDefault();document.querySelector('.stock-picker-item:not(:disabled)')?.click();return;}if(['invoices','orders'].includes(state.page)&&!state.modal&&!state.doc&&!state.busy){if(e.key==='F4'){e.preventDefault();state.stockSearch='';state.modal='pick-stock';renderDialog();}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&state.cart.length){e.preventDefault();if(!validateOrder())return;state.requestId=uid();state.modal='checkout';renderDialog();}}if(e.key==='Escape'&&!state.busy&&state.modal!=='setup'){if(state.modal==='checkout'){const form=$('[data-form="checkout"]');if(form)state.customer={...state.customer,...Object.fromEntries(new FormData(form))};}if(state.modal)state.modal=null;else state.doc=null;renderDialog();}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.data&&!state.modal&&!state.doc)refresh();});
window.addEventListener('beforeunload',e=>{if(state.cart.length){e.preventDefault();e.returnValue='';}});

function transactionPage(){
 const invoice=state.page==='invoices',c=state.customer;
 return `<section class="transaction-workspace" aria-label="${invoice?'Invoice':'Sales order'} entry">
 <header class="transaction-title"><div><span class="transaction-kicker">PARTY &amp; HOME / SALES DESK</span><h1>${invoice?'Invoice':'Sales order'}</h1></div><span class="badge neutral" title="Draft saved in this browser">Draft · auto-saved</span><div class="transaction-switch">${button('Invoice','nav',invoice?'primary':'','data-page="invoices"')}${button('Sales order','nav',!invoice?'primary':'','data-page="orders"')}</div></header>
 <div class="transaction-top">
 <section class="transaction-customer"><div class="customer-section-heading"><h2>${icon('users',17)}Customer details</h2>${button('Choose customer','pick-customer','small')}${button(icon('plus',14),'new-customer','small','aria-label="New customer"')}</div>${c.customerId?`<div class="selected-customer"><span>${escape(c.account)} · Saved customer</span>${button('Walk-in','walk-in','small')}</div>`:''}<div class="transaction-fields">
 ${field('Customer name',`<input data-customer="customer" value="${escape(c.customer)}" maxlength="200" placeholder="Walk-in customer" autocomplete="organization">`,true)}
 ${field('Phone / email',`<input data-customer="contact" value="${escape(c.contact)}" maxlength="300" placeholder="Customer contact details">`,true)}
 ${field('Billing address',`<textarea data-customer="address" maxlength="500" rows="2" placeholder="Street, town and postal code">${escape(c.address)}</textarea>`,true)}
 ${field('Deliver to',`<textarea data-customer="delivery" maxlength="500" rows="2" placeholder="Leave blank to use the billing address">${escape(c.delivery)}</textarea>`,true)}
 </div></section>
 <section class="transaction-brand">${shopLogo()}<strong>${escape(state.data.shop.name)}</strong><span>Every occasion. Every home.</span><p>${invoice?'Create an invoice to record the sale.':'Prepare a sales order, then invoice when confirmed.'}</p></section>
 <section class="transaction-details"><h2>${icon('file',17)}${invoice?'Invoice':'Order'} details</h2><div class="transaction-fields">
 ${field('Document no.',input('document-number','Automatic on save','readonly'))}${field('Date',input('document-date',date(new Date()),'readonly'))}
 ${field('Price type',`<select id="transaction-level" aria-label="Price type">${levels.map(l=>`<option value="${l}" ${l===state.level?'selected':''}>Price ${l.slice(1)}</option>`).join('')}</select>`)}
 ${invoice?field('Payment / terms',`<input data-customer="payment" value="${escape(c.payment||'Cash')}" maxlength="80" list="transaction-payments"><datalist id="transaction-payments"><option>Cash</option><option>Card</option><option>EFT</option><option>On account</option></datalist>`):field('Order type',input('order-type','Sales order / quotation','readonly'))}
 ${field('Your order / reference',`<input data-customer="orderRef" value="${escape(c.orderRef)}" maxlength="100" placeholder="Customer PO or reference">`)}${field('Delivery date',`<input type="date" data-customer="deliveryDate" value="${escape(c.deliveryDate)}">`)}
 </div><div class="transaction-notice">${icon(invoice?'box':'file',15)}${invoice?'Stock is deducted when processed.':'Stock stays unchanged until invoiced.'}</div></section>
 </div>
 <div class="transaction-line-toolbar"><div><h2>Line items <span data-transaction-count>${state.cart.length}</span></h2><p>Add stock, then adjust quantities and selling prices.</p></div><div>${button(icon('plus',17)+'Add stock <kbd>F4</kbd>','pick-stock','primary')}${button('Manual item','manual')}</div></div>
 <form data-form="scan" class="quick-entry"><label><span>Stock code / barcode</span><input id="quick-sku" name="sku" required autocomplete="off" placeholder="Type or scan SKU, then Enter" aria-label="Stock code or barcode"></label><label><span>Quantity</span><input name="qty" type="number" value="1" min="1" max="1000000" step="1" required aria-label="Quantity to add"></label><button class="button primary" type="submit">${icon('plus',16)}Add line</button><small>Exact codes add instantly. Other searches open the product picker.</small></form>
 <div class="transaction-table-scroll"><table class="transaction-table"><thead><tr><th>Ln</th><th>Stock code</th><th>Description</th><th>Unit</th><th>Quantity</th><th>Unit price (R)</th><th>Amount</th><th></th></tr></thead><tbody>
 ${state.cart.map((l,i)=>`<tr data-transaction-line="${l.key}"><td data-label="Line">${i+1}</td><td data-label="Stock code"><span class="transaction-sku">${escape(l.sku)}</span></td><td data-label="Description"><div class="transaction-product">${l.productId?picture(products().find(p=>p.id===l.productId)||{name:l.name,image:''}):''}<div><strong>${escape(l.name)}</strong>${l.productId&&products().find(p=>p.id===l.productId)?.packaging?`<small class="line-packaging">${escape(products().find(p=>p.id===l.productId).packaging)}</small>`:''}</div></div>${!l.productId?'<small>Manual item · No stock tracking</small>':''}</td><td data-label="Unit">${escape(l.unit)}</td><td data-label="Quantity"><div class="quantity"><button type="button" data-action="qty" data-key="${l.key}" data-delta="-1" aria-label="Decrease quantity">${icon('minus',13)}</button><input type="number" min="1" max="1000000" step="1" data-cart-qty="${l.key}" value="${l.qty}" aria-label="Quantity for ${escape(l.name)}"><button type="button" data-action="qty" data-key="${l.key}" data-delta="1" aria-label="Increase quantity">${icon('plus',13)}</button></div></td><td data-label="Unit price (R)"><input class="transaction-price" type="number" min="0" max="1000000" step="0.01" data-cart-price="${l.key}" value="${(l.price/100).toFixed(2)}" aria-label="Unit price for ${escape(l.name)}"></td><td data-label="Amount"><strong data-line-total="${l.key}">${money(l.qty*l.price)}</strong></td><td>${actionIcon('x','remove-line','Remove '+l.name,`data-key="${l.key}"`)}</td></tr>`).join('')}
 </tbody></table>${!state.cart.length?`<div class="transaction-empty">${icon('file',36)}<h3>Your ${invoice?'invoice':'sales order'} starts here</h3><p>Use Add stock to find a product by name or stock code.</p>${button(icon('plus',17)+'Add your first line','pick-stock','primary')}</div>`:''}</div>
 <div class="transaction-bottom"><label class="field transaction-message"><span>Delivery message / comments</span><textarea data-customer="notes" maxlength="1000" rows="3" placeholder="Delivery instructions or notes for the customer">${escape(c.notes)}</textarea></label><div class="transaction-totals"><div><span>Line items</span><strong data-transaction-lines>${state.cart.length}</strong></div><div><span>Total units</span><strong data-transaction-units>${units()}</strong></div><div class="transaction-grand-total"><span>Total (ZAR)</span><strong data-transaction-total>${money(total())}</strong></div><small>${state.data.printing?.vat_rate?'Prices include '+(state.data.printing.vat_rate/100)+'% VAT. Breakdown appears on your document.':'Prices as entered. No separate VAT calculation.'}</small></div></div>
 <footer class="transaction-actions"><div>${button(icon('x',17)+'Clear draft','clear','', '',!state.cart.length&&!Object.values(c).some(Boolean))}${button(icon('file',17)+'Saved documents','nav','','data-page="documents"')}</div><span class="transaction-shortcut">F4 Add stock · Ctrl + Enter Review &amp; save</span>${button(icon('check',18)+(invoice?'Process invoice':'Save sales order'),'checkout','primary transaction-save','',!state.cart.length)}</footer>
 </section>`;
}

function productMatches(p,query){
 const haystack=[p.name,p.sku,p.description,p.packaging,p.category].filter(Boolean).join(' ').toLowerCase();
 return query.trim().toLowerCase().split(/\s+/).every(word=>haystack.includes(word));
}
function stockmasterPage(){
 const filter=state.masterFilter||'active',department=state.masterDepartment||'';
 const list=products().filter(p=>(filter==='archived'?!p.active:p.active&&(filter!=='low'||p.stock<=p.low))&&(!department||p.category.toLowerCase()===department.toLowerCase())&&productMatches(p,state.search));
 return `<div class="stockmaster-summary"><span><strong>${active().length}</strong> active products</span><span><strong>${low().length}</strong> low stock</span><span>Pictures, descriptions and packaging in one place.</span></div><section class="panel stockmaster-tools"><div class="stockmaster-search">${searchBox('Search description, packaging or stock code…')}</div><div class="stockmaster-filters">${departmentFilter('stockmaster-department',department)}<label class="department-filter"><span>Show</span><select id="stockmaster-filter" aria-label="Stockmaster stock status">${[['active','Active products'],['low','Low stock'],['archived','Archived products']].map(([key,label])=>`<option value="${key}" ${filter===key?'selected':''}>${label}</option>`).join('')}</select></label><span class="stockmaster-count">${list.length} ${list.length===1?'product':'products'}</span></div></section><div class="stockmaster-grid">${list.map(p=>`<article class="stockmaster-card"><div class="stockmaster-photo">${picture(p,true)}<span class="stock-pill ${p.stock<=p.low?'warning':''}">${!p.active?'Archived':p.stock===0?'Out of stock':p.stock+' in stock'}</span>${!p.image?'<span class="no-product-photo">Add a product picture</span>':''}</div><div class="stockmaster-info"><div class="stockmaster-code">${escape(p.sku)} <span>${escape(p.category)}</span></div><h2>${escape(p.name)}</h2>${p.description?`<p class="stockmaster-description">${escape(p.description)}</p>`:''}<div class="stockmaster-packaging">${icon('box',18)}<div><span>Packaging / pack size</span><strong>${escape(p.packaging||'Not specified')}</strong></div></div><div class="stockmaster-unit"><span>Sold per <strong>${escape(p.unit)}</strong></span><span>${p.stock} ${escape(p.unit)} on hand</span></div><div class="stockmaster-prices">${levels.map(l=>`<div><span>${l.toUpperCase()}</span><strong>${money(p[l])}</strong></div>`).join('')}</div><div class="stockmaster-actions">${button(icon('edit',15)+'Edit product','edit-product','small',`data-id="${escape(p.id)}"`)}${button(icon('box',15)+'Adjust stock','stock','small',`data-id="${escape(p.id)}"`)}${supervisor()?actionIcon('archive','archive',p.active?'Archive product':'Restore product',`data-id="${escape(p.id)}"`):''}</div></div></article>`).join('')}</div>${!list.length?`<section class="panel">${empty(products().length?'No matching products':'Build your Stockmaster',products().length?'Try a different description, packaging or department.':'Add a picture, description, packaging and selling prices for each product.',button(icon('plus',17)+'Add product','new-product','primary'))}</section>`:''}`;
}
function stockPicker(){
 const matches=active().filter(p=>productMatches(p,state.stockSearch||''));
 return modal('Find stock','Check the picture, description and packaging, then select an item.',`<label class="search-box stock-picker-search">${icon('search',18)}<input id="stock-search" type="search" placeholder="Search description, packaging or stock code" aria-label="Search stock" value="${escape(state.stockSearch||'')}" autofocus></label><div class="visual-picker-heading"><span>${matches.length} ${matches.length===1?'matching item':'matching items'}</span><span>Price ${state.level.slice(1)} · ${state.kind==='invoice'?'Invoice':'Sales order'}</span></div><div class="stock-picker-list visual-stock-picker">${matches.map(p=>`<button type="button" class="stock-picker-item visual-stock-item" data-action="pick-product" data-id="${escape(p.id)}" ${state.kind==='invoice'&&p.stock<=0?'disabled':''}>${picture(p)}<span class="visual-stock-details"><small class="visual-stock-code">${escape(p.sku)} · ${escape(p.category)}</small><strong>${escape(p.name)}</strong>${p.description?`<span class="visual-stock-description">${escape(p.description)}</span>`:''}<span class="visual-stock-packaging">${icon('box',14)}Packaging: <b>${escape(p.packaging||'Not specified')}</b></span><small>${p.stock} ${escape(p.unit)} in stock · Sold per ${escape(p.unit)}${state.cart.some(l=>l.productId===p.id)?' · '+state.cart.filter(l=>l.productId===p.id).reduce((n,l)=>n+l.qty,0)+' in this order':''}</small><span class="visual-stock-price">${money(p[state.level])}<span>${p.stock<=0&&state.kind==='invoice'?'Out of stock':'Add to '+(state.kind==='invoice'?'invoice':'order')+' +'}</span></span></span></button>`).join('')||'<p class="panel-empty">No matching products. Try a different description, packaging or stock code.</p>'}</div>`,true);
}

const customers=()=>state.data?.customers||[];
function chooseCustomer(id){
 const c=customers().find(c=>c.id===id&&c.active);if(!c)return;
 state.customer={...state.customer,customerId:c.id,customer:c.name,contact:[c.phone,c.email].filter(Boolean).join(' · '),address:c.address,delivery:c.delivery,account:c.account,customerVat:c.vat,payment:c.terms};
 state.level=c.level;state.cart.forEach(l=>{const p=products().find(p=>p.id===l.productId);if(p)l.price=p[state.level];});persistDraft();
}
function customersPage(){
 const query=state.search.trim().toLowerCase(),list=customers().filter(c=>`${c.name} ${c.account} ${c.phone} ${c.email}`.toLowerCase().includes(query));
 return `<div class="customer-summary"><span><strong>${customers().filter(c=>c.active).length}</strong> active customers</span><span>Choose a customer in any invoice or sales order to fill in their details.</span></div><section class="panel"><div class="table-toolbar">${searchBox('Search customer, account, phone or email…')}</div><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Account</th><th>Contact</th><th>Terms / price</th><th>Status</th><th>Manage</th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${escape(c.name)}</strong><small class="customer-address">${escape(c.address)}</small></td><td>${escape(c.account)}</td><td><div>${escape(c.phone)}</div><small>${escape(c.email)}</small></td><td>${escape(c.terms)} · ${c.level.toUpperCase()}</td><td><span class="badge ${c.active?'green':'neutral'}">${c.active?'Active':'Archived'}</span></td><td><div class="row-actions">${button('History','customer-history','small',`data-id="${escape(c.id)}"`)}${button('Edit','edit-customer','small',`data-id="${escape(c.id)}"`)}${supervisor()?button(c.active?'Archive':'Restore','archive-customer','small',`data-id="${escape(c.id)}"`):''}</div></td></tr>`).join('')}</tbody></table></div>${!list.length?empty('Get to know your customers','Save customer details and reuse them every time they shop.',button('Add customer','new-customer','primary'),'users'):''}</section>`;
}
function customerModal(){
 const c=state.editCustomer||{},used=new Set(customers().map(c=>c.account.toLowerCase()));let next=customers().length+1;while(used.has('c'+String(next).padStart(4,'0')))next++;
 return modal(c.id?'Edit customer':'New customer','Save contact, delivery and pricing preferences for future sales.',`<form data-form="customer"><div class="form-grid">${field('Customer / business name',input('name',c.name||state.customer?.customer,'required maxlength="200" autofocus'),true)}${field('Account code',input('account',c.account||'C'+String(next).padStart(4,'0'),'required maxlength="60"'))}${field('VAT number (optional)',input('vat',c.vat,'maxlength="80"'))}${field('Phone',input('phone',c.phone,'type="tel" maxlength="100"'))}${field('Email',input('email',c.email,'type="email" maxlength="200"'))}${field('Billing address',`<textarea name="address" maxlength="500" rows="3">${escape(c.address)}</textarea>`,true)}${field('Delivery address (if different)',`<textarea name="delivery" maxlength="500" rows="3">${escape(c.delivery)}</textarea>`,true)}${field('Default payment / terms',input('terms',c.terms||'Cash','required maxlength="80"'))}${field('Default price level',`<select name="level">${levels.map(l=>`<option value="${l}" ${l===(c.level||'p1')?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select>`)}</div><p class="helper">Selecting this customer fills the document details and applies their price level to inventory lines. Changes to a customer never alter saved documents.</p>${footer('Save customer')}</form>`,true);
}
function customerPicker(){
 const q=(state.customerSearch||'').toLowerCase();
 return modal('Choose customer','Search by name, account code, phone or email. Choosing a customer applies their saved price level.',`<label class="search-box stock-picker-search">${icon('search',18)}<input id="customer-search" type="search" value="${escape(state.customerSearch||'')}" placeholder="Search customers" aria-label="Search customers" autofocus></label><div class="stock-picker-list">${customers().filter(c=>c.active&&`${c.name} ${c.account} ${c.phone} ${c.email}`.toLowerCase().includes(q)).map(c=>`<button class="stock-picker-item" data-action="use-customer" data-id="${escape(c.id)}"><span class="avatar">${escape(c.name[0])}</span><span><strong>${escape(c.name)}</strong><small>${escape(c.account)} · ${escape(c.phone||c.email)} · ${c.level.toUpperCase()}</small></span>${icon('plus',17)}</button>`).join('')||'<p class="panel-empty">No matching customers. Add a new customer to save their details.</p>'}</div><div class="modal-footer">${button('Cancel','close-modal')}${button(icon('plus',16)+'New customer','new-customer','primary')}</div>`,true);
}
function checkoutFooter(){return `<div class="modal-footer checkout-footer">${button('Back','close-modal')}<button class="button" data-save>${state.kind==='invoice'?'Save invoice':'Save sales order'}</button><button class="button primary" data-save data-print-after="true">${icon('print',17)}Save &amp; print</button></div>`;}
function printingSettings(){
 if(state.data.role!=='owner')return '';
 const p=state.data.printing||{};
 return `<section class="panel settings-card"><div class="panel-title"><div><h2>Print settings</h2><p>Your details for invoices and sales order notes.</p></div>${icon('print',22)}</div><form data-form="printing"><div class="form-grid">${field('Shop VAT number',input('vat',p.vat,'maxlength="160"'))}${field('VAT included in prices (%)',input('vat_rate',((p.vat_rate||0)/100).toFixed(2),'type="number" min="0" max="100" step="0.01" required'))}${field('Bank name',input('bank',p.bank,'maxlength="160"'))}${field('Account name',input('account_name',p.account_name,'maxlength="160"'))}${field('Bank account number',input('account_number',p.account_number,'maxlength="160"'))}${field('Branch code',input('branch',p.branch,'maxlength="160"'))}${field('Printed footer / payment instructions',`<textarea name="footer" maxlength="500" rows="3" placeholder="e.g. Use your invoice number as the payment reference">${escape(p.footer)}</textarea>`,true)}</div><p class="helper">VAT is off by default. If you enable it, the app treats selling prices as VAT-inclusive and shows the included VAT breakdown. Enter only your own business and banking details. Settings are captured when each document is saved.</p><button class="button primary" data-save>Save print settings</button></form></section>`;
}
function addStock(p,qty=1){
 if(!p||!Number.isInteger(qty)||qty<1||qty>1000000){notify('Enter a whole quantity between 1 and 1,000,000.');return false;}
 const existing=state.cart.find(l=>l.productId===p.id),count=(existing?.qty||0)+qty;
 if(count>1000000){notify('Maximum quantity is 1,000,000 per line.');return false;}
 if(state.kind==='invoice'&&count>p.stock){notify(`Only ${p.stock} ${p.unit} of ${p.name} available. Use a sales order for unconfirmed stock.`);return false;}
 if(!existing&&state.cart.length>=100){notify('A document can contain up to 100 lines.');return false;}
 if(existing)existing.qty=count;else state.cart.push({key:uid(),productId:p.id,name:p.name,sku:p.sku,unit:p.unit,qty,price:p[state.level]});persistDraft();return true;
}
function validateOrder(){
 if(!state.cart.length){notify('Add at least one line first.');return false;}
 const quantities=new Map();
 for(const l of state.cart){
 if(!Number.isInteger(l.qty)||l.qty<1||l.qty>1000000||!Number.isInteger(l.price)||l.price<0||l.price>100000000){notify('Check the quantities and prices before saving.');return false;}
 if(l.productId){const p=products().find(p=>p.id===l.productId&&p.active);if(!p){notify('An item is no longer available. Remove it before saving.');return false;}quantities.set(p.id,(quantities.get(p.id)||0)+l.qty);if(state.kind==='invoice'&&quantities.get(p.id)>p.stock){notify(`Not enough stock for ${p.name}: ${p.stock} ${p.unit} available.`);return false;}}
 }return true;
}
function draftKey(){return state.data?.shop&&state.data?.user?'party-home-draft-v1:'+state.data.user.email:null;}
function persistDraft(){
 try{const key=draftKey();if(!key||typeof localStorage==='undefined')return;const hasDraft=state.cart.length||Object.values(state.customer).some(Boolean);if(!hasDraft){localStorage.removeItem(key);return;}localStorage.setItem(key,JSON.stringify({cart:state.cart,customer:state.customer,kind:state.kind,level:state.level,page:state.page,updated:Date.now()}));}catch{}
}
function restoreDraft(){
 const key=draftKey();if(!key||state.loadedDraft===key)return;state.loadedDraft=key;
 try{if(typeof localStorage==='undefined')return;const saved=JSON.parse(localStorage.getItem(key)||'null');if(!saved||!Array.isArray(saved.cart)||saved.cart.length>100)return;state.cart=saved.cart.filter(l=>l&&typeof l.key==='string'&&typeof l.name==='string'&&Number.isInteger(l.qty)&&l.qty>0&&l.qty<=1000000&&Number.isInteger(l.price)&&l.price>=0&&l.price<=100000000);state.customer=saved.customer&&typeof saved.customer==='object'&&!Array.isArray(saved.customer)?saved.customer:{};state.kind=saved.kind==='quote'?'quote':'invoice';state.level=levels.includes(saved.level)?saved.level:'p1';if(['sale','orders','invoices'].includes(saved.page))state.page=saved.page;if(state.cart.length)notify('Your unfinished order has been restored. Check stock before saving.');}catch{}
}
function copyOrder(id){
 if(state.cart.length||Object.values(state.customer).some(Boolean)){notify('Save or clear the current draft before copying a document.');return;}
 const d=docs().find(d=>d.id===id);if(!d)return;const x=d.details||{};
 const copied=lines().filter(l=>l.document_id===id);if(copied.some(l=>l.product_id&&!products().some(p=>p.id===l.product_id&&p.active))){notify('This document contains archived products. Restore them before copying.');return;}
 state.cart=copied.map(l=>({key:uid(),productId:l.product_id,name:l.name,sku:l.sku,unit:l.unit,qty:l.qty,price:l.price}));
 state.customer={customerId:x.customerId&&customers().some(c=>c.id===x.customerId&&c.active)?x.customerId:null,customer:d.customer,contact:d.contact,address:d.address,notes:d.notes,payment:d.payment,account:x.account,customerVat:x.customerVat,delivery:x.delivery,orderRef:'',deliveryDate:''};
 state.level=d.level;state.kind='quote';state.page='orders';state.doc=null;state.modal=null;render();notify('Copied to a new sales order draft. Stock is unchanged.');
}
function printDocument(d){
 const x=d.details||{},shop=x.shop||state.data.shop,p=x.printing||{},source=docs().find(q=>q.id===d.quote_id),items=lines().filter(l=>l.document_id===d.id),amount=docTotal(d),net=p.vat_rate?Math.round(amount*10000/(10000+p.vat_rate)):amount,vat=amount-net;
 const pages=[];let chunk=[],used=0;for(const l of items){const size=Math.max(1,Math.ceil(l.name.length/52));if(used+size>22&&chunk.length){pages.push(chunk);chunk=[];used=0;}chunk.push(l);used+=size;}if(chunk.length||!pages.length)pages.push(chunk);
 const title=d.kind==='quote'?'Sales - Order Note':p.vat_rate&&p.vat?'Tax Invoice':'Invoice';
 const detailsRow=(label,value)=>`<tr><th>${escape(label)}</th><td>${escape(value||'—')}</td></tr>`;
 return `<div class="document-overlay"><div class="document-tools">${button(icon('x',18)+'Close','close-doc')}<div>${d.kind==='quote'&&!docs().some(q=>q.quote_id===d.id)?button(icon('file',18)+'Convert to invoice','convert','primary'):''}${button('Copy to new order','copy-order','','data-id="'+escape(d.id)+'"')}${button(icon('print',18)+'Print / Save PDF','print','primary')}</div></div><div class="print-pages">${pages.map((page,index)=>`<article class="print-document business-document"><header class="business-header"><div class="business-company">${shopLogo()}<div><h2>${escape(shop.name)}</h2><p class="preserve-lines">${escape(shop.address)}</p><p>${escape(shop.contact)}</p>${p.vat?`<p>VAT Reg No: ${escape(p.vat)}</p>`:''}</div></div><div class="document-meta"><h1>${escape(title)}</h1><h2>${docNo(d)}</h2><p>Page ${index+1} of ${pages.length}</p></div></header>
 <div class="business-details"><div class="business-addresses"><section><h3>Sold to / Customer details</h3><strong>${escape(d.customer)}</strong>${x.account?`<p>Account: ${escape(x.account)}</p>`:''}<p class="preserve-lines">${escape(d.address)}</p><p>${escape(d.contact)}</p>${x.customerVat?`<p>Customer VAT No: ${escape(x.customerVat)}</p>`:''}</section><section><h3>Deliver to</h3><p class="preserve-lines">${escape(x.delivery||d.address||'Collect in store')}</p></section></div><table class="business-document-details"><tbody>${detailsRow('Document no.',docNo(d))}${detailsRow('Document date',date(d.created))}${detailsRow('Your order / reference',x.orderRef)}${detailsRow('Delivery date',x.deliveryDate?date(x.deliveryDate+'T12:00:00+02:00'):'')}${detailsRow('Terms',d.kind==='quote'?'Sales order / quotation':d.payment)}${detailsRow('Price type',d.level.toUpperCase())}${detailsRow('Sales representative',x.salesRep||d.actor)}${source?detailsRow('From sales order',docNo(source)):''}</tbody></table></div>
 <div class="business-items"><table><thead><tr><th>Ln</th><th>Stock code</th><th>Description</th><th>Unit</th><th>Quantity</th><th>Unit price${p.vat_rate?' incl. VAT':''}</th><th>Amount${p.vat_rate?' incl. VAT':''}</th></tr></thead><tbody>${page.map(l=>`<tr><td>${items.indexOf(l)+1}</td><td>${escape(l.sku)}</td><td>${escape(l.name)}</td><td>${escape(l.unit)}</td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(l.qty*l.price)}</td></tr>`).join('')}</tbody></table></div>
 ${index===pages.length-1?`<div class="business-summary"><section><p>Total quantity: <strong>${items.reduce((n,l)=>n+l.qty,0)}</strong> &nbsp; Line items: <strong>${items.length}</strong></p>${d.notes?`<h4>Delivery message / comments</h4><p class="preserve-lines">${escape(d.notes)}</p>`:''}<div class="business-signature"><span>Received by: ____________________</span><span>Signature: ____________________</span></div></section><table><tbody>${detailsRow('Subtotal'+(p.vat_rate?' excl. VAT':''),money(net))}${p.vat_rate?detailsRow('Included VAT ('+(p.vat_rate/100)+'%)',money(vat)):''}<tr class="business-total"><th>TOTAL (ZAR)</th><td>${money(amount)}</td></tr></tbody></table></div><footer class="business-footer">${p.bank||p.account_number?`<section><h3>Banking details</h3><p>Account name: ${escape(p.account_name||shop.name)}</p><p>Bank: ${escape(p.bank)}</p><p>Account no: ${escape(p.account_number)}</p><p>Branch: ${escape(p.branch)}</p></section>`:''}<section><p class="preserve-lines">${escape(p.footer||'Thank you for shopping with '+shop.name+'.')}</p><p class="document-stock-note">${d.kind==='quote'?'NOT FOR DESPATCHING · Stock is not reserved or deducted.':'Please retain this invoice for your records.'}</p>${!p.vat_rate?'<small>No separate VAT calculation.</small>':''}<small>Prepared by: ${escape(x.salesRep||d.actor||'Shop team')}</small></section></footer>`:`<div class="business-continued">Continued on page ${index+2} · Totals and payment details on the final page.</div>`}
 </article>`).join('')}</div></div>`;
}

try{state.local=(await request('/api/auth/status')).local;}catch{state.local=false;}
await refresh();
